        {
          "text": " ",
          "color": "000000",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "[النساء: 66]",
          "color": "5B626B",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "، ويتصل بها وعد الأجر والهدى وصحبة المنعم عليهم: ",
          "color": "000000",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "﴿وَإِذًا لَّـَٔاتَيْنَـٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا وَلَهَدَيْنَـٰهُمْ صِرَٰطًا مُّسْتَقِيمًا وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَ ۚ وَحَسُنَ أُو۟لَـٰٓئِكَ رَفِيقًا ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ عَلِيمًا﴾",
          "color": "176744",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": " ",
          "color": "000000",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "[النساء: 67–70]",
          "color": "5B626B",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": " والحياة الطيبة للمؤمن العامل: ",
          "color": "000000",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "﴿مَنْ عَمِلَ صَـٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ﴾",
          "color": "176744",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": " ",
          "color": "000000",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "[النحل: 97]",
          "color": "5B626B",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": ". فالدعاء والتقوى ومجاهدة الخواطر وجوه متكاملة لحفظ القلب، مع اليقين أن زمام القلوب وميزان الرفع والخفض بيد الرحمن.",
