            "text": "﴿وَٱللَّهُ يَقْضِى بِٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ ۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[غافر: 20]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ويأمر بالعدل: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَـٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النحل: 90]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ووضع الميزان ونهى عن الطغيان فيه وأمر بإقامته بالقسط: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الرحمن: 7–9]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ولهذا اجتمع في كلمته صدق الأخبار وعدل الأحكام: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأنعام: 115]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ويظهر هذا العدل يوم توضع الموازين فلا تظلم نفس شيئا، ولو كان عملها مثقال حبة من خردل أحضر: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَـٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَـٰسِبِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأنبياء: 47]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ومن عدله أن المحسن من غير أهل الإيمان لا يحرم جزاء إحسانه الدنيوي، فيعطى منه ما شاء الله من رزق وعافية ونحوهما، وإن لم يكن له مع الكفر نصيب من ثواب الآخرة. وحتى من انتهى إلى العذاب لا يبقى له احتجاج صحيح على ربه؛ إذ تقر النفوس عند انكشاف الحق بأنها كذبت الرسل وظلمت نفسها، كما في اعتراف أهل السعير بذنبهم: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَـٰلٍ كَبِيرٍ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الملك: 9]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَـٰبِ ٱلسَّعِيرِ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الملك: 11]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وشهادتهم على أنفسهم بالكفر: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأنعام: 130]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ أُو۟لَـٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَـٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأعراف: 37]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقد قال عنهم: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَمَا ظَلَمْنَـٰهُمْ وَلَـٰكِن كَانُوا۟ هُمُ ٱلظَّـٰلِمِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الزخرف: 76]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقولهم حين يحضر الوعد: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَـٰذَا بَلْ كُنَّا ظَـٰلِمِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأنبياء: 97]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ وينتهي التخاصم إلى استسلامهم: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الصافات: 26]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ومن الصور التي تجسد لزوم إنصاف الضعيف ما رواه جابر عن العائدين من الحبشة: مرت عجوز من رهابينهم تحمل قلة ماء على رأسها، فدفعها فتى حتى وقعت وانكسرت قلتها، فذكرته بموقف يجمع الله فيه الأولين والآخرين وتتكلم الأيدي والأرجل بما كسب أصحابها، وأنها ستعرف حينئذ كيف يكون أمرها وأمره عند الله. فقال النبي ﷺ: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«صدقت، صدقت، كيف يقدس الله أمة لا يؤخذ لضعيفهم من شديدهم»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[ابن ماجه: 4010]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فتعظيم عدل الله لا ينفصل عن رد الظلم عن خلقه؛ ولهذا عقب سبحانه على تحريمه على نفسه بقوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«وجعلته بينكم محرما فلا تظالموا»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، فجمع الحكم والنهي المؤكد. والظلم وضع الشيء في غير موضعه، وأعظمه صرف العبادة إلى غير مستحقها: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[لقمان: 13]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ويظلم المرء نفسه بالمعصية، ويظلم غيره في دم أو مال أو عرض أو حق. وعلى قدر ما يؤدي من الحقوق يكون عدله: حق الله أن يعرفه ويعبده ويخلص له، وحق رسوله ﷺ الإيمان به ومحبته وطاعته وتقديم هديه، وحق الوالدين البر، وحق الأرحام الصلة، وحقوق الأصحاب والمعاملين والزوجين الوفاء والإنصاف. والإيمان بأصوله وفروعه عدل، والإخلال بشيء من هذه الحقوق ظلم بحسبه، وقد قال تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأعراف: 29]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وربط الأمن والاهتداء بالإيمان الذي لم يلبس بظلم: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَـٰنَهُم بِظُلْمٍ أُو۟لَـٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأنعام: 82]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وجمع النبي ﷺ حرمة الاعتداء بقوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«فإن دماءكم وأموالكم وأعراضكم بينكم حرام كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البخاري: 67]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقال: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«الظلم ظلمات يوم القيامة»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البخاري: 2447؛ مسلم: 2579]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ فكما أن العدل يثمر نورا يسعى بين أيدي المؤمنين وبأيمانهم: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الحديد: 12]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، فإن الظلم يعود على صاحبه ظلمات بقدر ما اكتسب. والظلم من جهة عاقبته ثلاثة: شرك لا يغفر لمن مات عليه، وحقوق للعباد لا تترك بغير فصل وإنصاف، وذنوب دون الشرك بين العبد وربه تدخل تحت مشيئته: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النساء: 48]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فلا يكفي أن يطلب المعتدي المغفرة ويبقي المظلمة في يده؛ بل يتداركها ما دام يستطيع التحلل ورد الحقوق، امتثالا لقوله ﷺ: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«من كانت له مظلمة لأحد من عرضه أو شيء فليتحلله منه اليوم، قبل أن لا يكون دينار ولا درهم»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "؛ فإن لم يفعل أخذ للمظلوم من حسناته، فإن نفدت حمل من سيئات صاحبه ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البخاري: 2449]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ثم ينتقل الحديث من عدل الرب إلى افتقار الخلق: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«كلكم ضال إلا من هديته»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«كلكم جائع إلا من أطعمته»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«كلكم عار إلا من كسوته»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": ". إنها حاجات لا يخرج عنها نبي ولا ولي ولا غني ولا قوي؛ فالعبد فقير في وجوده وصفاته وأفعاله، لا يملك لنفسه هداية ولا بقاء ولا صلاحا استقلالا، وهو معنى قوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿يَـٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ ۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[فاطر: 15]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ويضم الحديث سؤال ما يصلح الدين، وهو الهداية والمغفرة، إلى ما يقوم به البدن، وهو الطعام والكساء، وجاء في رواية ذكر الظمأ والسقي أيضا ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[أحمد: 21420]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فلا حول للعبد ولا قوة إلا بالله، ومن هداه الله فهو المهتدي، ومن أضله لا يجد وليا مرشدا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ ۖ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَـٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا ۖ مَّأْوَىٰهُمْ جَهَنَّمُ ۖ كُلَّمَا خَبَتْ زِدْنَـٰهُمْ سَعِيرًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الإسراء: 97]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍ مِّنْهُ ۚ ذَٰلِكَ مِنْ ءَايَـٰتِ ٱللَّهِ ۗ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّا مُّرْشِدًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الكهف: 17]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وما يفتح الله للناس من رحمة لا ممسك لها، وما يمسك فلا مرسل له من بعده: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا ۖ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[فاطر: 2]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وليست الأسباب منفية، ولكنها لا تستقل بالإيجاد ولا بضمان النتائج؛ فالعمل والتجارة والميراث والهدية والشراكة والزراعة أبواب يفتحها مسببها، فيباشرها العبد ويعلق قلبه بربها. ولهذا قيل: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[العنكبوت: 17]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وقد جمع إبراهيم عليه السلام هذا المعنى حين برئ مما يعبد قومه إلا رب العالمين، ثم وصفه بأنه خلقه ويهديه، ويطعمه ويسقيه، ويشفيه إذا مرض، ويميته ثم يحييه، وهو الذي يرجو مغفرته يوم الدين: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ أَنتُمْ وَءَابَآؤُكُمُ ٱلْأَقْدَمُونَ فَإِنَّهُمْ عَدُوٌّ لِّىٓ إِلَّا رَبَّ ٱلْعَـٰلَمِينَ ٱلَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ وَٱلَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الشعراء: 75–82]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ فمن انفرد بهذه الربوبية استحق أن يفرد بالعبادة والسؤال. ويسوق القرآن البرهان نفسه: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۖ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الروم: 40]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". والاستهداء والاستطعام والاستكساء والاستغفار إقرار عملي بهذه الحقيقة؛ وقد أمر النبي ﷺ: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الترمذي: 2516]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ولا يستنكف المؤمن من أن يسأله حاجة صغيرة؛ فالمحتاج محتاج في دقيق أمره وجليله، وكان من السلف من يسأله ملح عجينه وعلف دابته. ورُوي الحث على سؤال الله حتى شسع النعل إذا انقطع ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الترمذي: 3604]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ومن دعاء موسى وهو في غربته وحاجته: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[القصص: 24]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ فإذا فتح الله باب رزق أو علم لم ينقلب هذا الافتقار دعوى استغناء، كما قال قارون: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[القصص: 78]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، بل ازداد صاحبه اعترافا بالمنة وشكرا. والحاجة إلى الهداية أعظم وأدوم من الحاجة إلى الطعام؛ فالطعام يقيم البدن، والهداية تصلح سبيله ومآله. وليس طلبها مقصورا على انتقال الكافر إلى الإسلام؛ إذ يكرر المؤمن في صلاته ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الفاتحة: 6]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، يسأل الثبات على أصل الهدى، والزيادة منه، والنجاة من الزيغ بعده، ومعرفة ما لم يعرف من تفاصيل الحق والعمل بما عرف. فهداية الاعتقاد والتوحيد والسنة، وهداية العلم بالحلال والحرام، وحسن الفهم والترجيح، وهداية الإرادة إلى الإخلاص والخشية والرجاء والمحبة، وهداية الجوارح إلى الطاعة، وهداية الخلق إلى العدل والرحمة، كلها حاجات تتجدد. ولهذا كان من دعائه ﷺ: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«واهدني لأحسن الأخلاق لا يهدي لأحسنها إلا أنت، واصرف عني سيئها لا يصرف عني سيئها إلا أنت»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 771]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ومن جوامع دعائه: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«اللهم إني أسألك الهدى والتقى والعفاف والغنى»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2721]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فالهدى علم نافع وبصيرة، والتقى عمل بطاعة الله واجتناب لمساخطه، والعفاف صيانة عن الحرام والتطلع إلى ما في أيدي الناس، والغنى غنى القلب وكفايته ورضاه؛ فقد يملك المرء أموالا كثيرة ويبقى قلبه فقيرا بالحرص والتسخط، وقد يرزق الكفاية فيستغني بها عن مذلة السؤال. وكذلك لا يسقط الاستطعام عن الغني؛ فقد يذهب ماله في ليلة، وقد يبقى الطعام أمامه ويمنعه المرض من أكله أو الانتفاع به. فالنعمة ليست ثمن الطعام وحده، بل تحصيله وأمنه وشهوة تناوله والقدرة على هضمه والانتفاع به والتخلص مما يؤذيه. ومن عرف هذا لم يجعل قلبه أسيرا لباب غني مثله، بل طلب من الله وابتغى الأسباب المشروعة. والكساء نعمة ستر وحماية وزينة، ويصل سؤالها الظاهر بالباطن قوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿يَـٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأعراف: 26]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ فيسأل العبد ستر عورته واستقامة قلبه وعمله جميعا. ثم يكشف قوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إنكم تخطئون بالليل والنهار»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " واقع العبد المتكرر، ويقابله بقوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«وأنا أغفر الذنوب جميعا»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "؛ فالذنوب لفظ عام، وأكد العموم بقوله ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«جميعا»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، وقدم الوعد بالمغفرة على الأمر بطلبها، حتى لا يحجب الخجل أو عظم الجناية صاحبه عن الرجوع. ولذلك قال تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الزمر: 53]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ودعا إلى المسارعة والمسابقة إلى مغفرته: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[آل عمران: 133]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الحديد: 21]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وأخبر أنه يقبل التوبة عن عباده ويعفو عن السيئات: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَـٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[التوبة: 104]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقوله تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الشورى: 25]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وأن من يعمل سوءا أو يظلم نفسه ثم يستغفر يجده غفورا رحيما: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النساء: 110]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وهذه بشارة تدعو إلى التوبة والإيمان والعمل والثبات، كما قال: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحًا ثُمَّ ٱهْتَدَىٰ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[طه: 82]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وليست ترخيصا في الإصرار. وقد بدأ آدم وزوجه طريق الرجوع بالاعتراف: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأعراف: 23]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وكان النبي ﷺ، مع منزلته ومغفرة ذنبه، يستغفر في اليوم أكثر من سبعين مرة ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البخاري: 6307]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وجاء عنه أنه يتوب إلى الله في اليوم مائة مرة ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2702]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ فكيف بمن كثرت غفلته وتقصيره؟ وقال ﷺ: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«والذي نفسي بيده لو لم تذنبوا لذهب الله بكم ولجاء بقوم يذنبون فيستغفرون الله فيغفر لهم»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2749]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ والمقصود فتح باب الاستغفار وبيان حب الله للتوبة والمغفرة، لا طلب المعصية لذاتها. ومن تمام هذا الرجاء قوله تعالى في الحديث القدسي: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«يا ابن آدم إنك ما دعوتني ورجوتني غفرت لك على ما كان فيك ولا أبالي»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، وقوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«لو بلغت ذنوبك عنان السماء ثم استغفرتني غفرت لك»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، وقوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إنك لو أتيتني بقراب الأرض خطايا ثم لقيتني لا تشرك بي شيئا لأتيتك بقرابها مغفرة»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الترمذي: 3540]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فعنان السماء السحاب وما علا منها، وقراب الأرض ما يقارب ملأها؛ ويقترن اتساع المغفرة هنا بالدعاء والرجاء والاستغفار والتوحيد. ومن تأمل أسماء ربه لم يجعل تقصيره أكبر من رحمة مولاه؛ فالقنوط ينشأ من الجهل بالغفور الرحيم القادر على كشف الضر، وقد نهى يعقوب بنيه عن اليأس من روح الله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿يَـٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَـٰفِرُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[يوسف: 87]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وقال إبراهيم: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الحجر: 56]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وأخبر الرب أن رحمته وسعت كل شيء: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَٱكْتُبْ لَنَا فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَـٰتِنَا يُؤْمِنُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأعراف: 156]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وهو سبحانه يبسط يده بالليل ليتوب مسيء النهار، وبالنهار ليتوب مسيء الليل حتى تطلع الشمس من مغربها ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2759]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ومن دقة هذا المعنى أن العبد يعصي بقدرة ورزق أنعم الله بهما عليه، ثم يستره الغني عنه ويمهله ويفتح له التوبة؛ فمقابلة الإحسان بالإساءة تقتضي حياء وانكسارا، ومواصلة الرب إحسانه تقتضي رجاء ومحبة وشكرا. ويحتاج السؤال الذي أمر به الحديث إلى قلب حاضر يعرف من يسأل، ويوقن بقدرته وصدق وعده: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[غافر: 60]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". والدعاء يظهر فقر العبد واعترافه بغنى ربه وقدرته، ولذلك جاء: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«ليس شيء أكرم على الله تعالى من الدعاء»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الترمذي: 3370]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وجاء: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إن ربكم حيي كريم يستحيي من عبده أن يرفع إليه يديه فيردهما صفرا»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[ابن ماجه: 3865]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وفي الحديث القدسي: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«أنا عند ظن عبدي بي وأنا معه إذا دعاني»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2675]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فاليقين بالدعاء إحسان ظن بالله، وقد روي: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«ادعوا الله وأنتم موقنون بالإجابة، واعلموا أن الله لا يستجيب دعاء من قلب غافل لاه»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الترمذي: 3479]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". والدعاء مع قلب غافل كالسهم يخرج من قوس رخوة؛ تضعف قوته بضعف ما يسنده. ويكون الدعاء تضرعا وخفية: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأعراف: 55]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، مع ترك العدوان والإثم والقطيعة والظلم وأكل الحرام وسائر ما يحجب صاحبه؛ فلا يكون دعاء الوالد على ولد امتنع من معصية أمرا مشروعا بمجرد صدوره من والد، إذ لا يحب الله المعتدين: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَـٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البقرة: 190]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ومع تعلم أسباب الإجابة يتعلم المؤمن موانعها وما يحبط العمل أو يذهب ثوابه، ليصلح ما في قلبه وسلوكه. ولا تعني الثقة أن يوجب الداعي على الله صورة بعينها من الإجابة أو توقيتها؛ فقد بين النبي ﷺ أن المسلم إذا دعا دعوة ليس فيها إثم ولا قطيعة رحم أعطاه الله بها إحدى ثلاث: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إما أن تعجل له دعوته، وإما أن يدخرها له في الآخرة، وإما أن يصرف عنه من السوء مثلها»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": "، فلما قالوا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إذا نكثر»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " قال: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«الله أكثر»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[أحمد: 11133]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ويأتي قوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«لن تبلغوا ضري فتضروني، ولن تبلغوا نفعي فتنفعوني»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ليخلص التعبد من توهم المعاوضة مع رب محتاج؛ فلا يطلب الله من عباده رزقا ولا عونا، ولا تبلغ معصيتهم منه ما تبلغه أذية المخلوق من المخلوق. وما ورد في حديث الدهر: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«يؤذيني ابن آدم»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البخاري: 4826؛ مسلم: 2246]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وفي ذكر الذين يؤذون الله ورسوله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الأحزاب: 57]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، لا يقتضي تمكنهم من الإضرار به؛ فإن الأذى المذكور لا يساوي الضرر المنفي، وقد نص القرآن على أن من ينقلب على عقبيه لن يضر الله شيئا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّـٰكِرِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[آل عمران: 144]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وأن الكافرين الصادين عن سبيله لن يضروه شيئا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَـٰلَهُمْ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[محمد: 32]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وطاعة الخلق لا تزيد ملكه ومعصيتهم لا تنقصه، ولو اجتمع أولهم وآخرهم وإنسهم وجنهم على أتم تقوى أو أشد فجور. وفي إسناد التقوى والفجور إلى القلب بيان أن الأصل باطن الإنسان، وعنه تصدر أعمال جوارحه؛ وقد أشار ﷺ إلى صدره وقال: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«التقوى هاهنا»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2564]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ونفع هذه التقوى يعود إلى صاحبها، فلا يمن بصلاته أو صلاحه على ربه: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَـٰنِ إِن كُنتُمْ صَـٰدِقِينَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الحجرات: 17]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ولا يتوهم أن صورة العبادة وحدها هي المقصودة، إذ قال تعالى في القربان: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَـٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الحج: 37]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". فإحسان الله ليس استجلابا لمنفعة ولا دفعا لمضرة، وإنما يأمر بما يصلح عباده ويحب ما ينفعهم، وهو غني عن الجميع. ثم يفتح الحديث للقلب مشهد السعة: جميع الأولين والآخرين من الإنس والجن في صعيد واحد، لكل فرد منهم حاجاته ورغباته، فيعطي كل إنسان مسألته، فلا تنقص خزائنه. والمخيط الإبرة؛ اختيرت لصغرها وملاستها وقلة ما يعلق بها من الماء، وقوبلت بالبحر ليقرب المعنى إلى الحس، لا لإثبات أن ملك الله ينقص نقصا يسيرا؛ فما عنده لا ينفد: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿مَا عِندَكُمْ يَنفَدُ ۖ وَمَا عِندَ ٱللَّهِ بَاقٍ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النحل: 96]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وإنما أمره إذا أراد شيئا أن يقول له كن فيكون: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[يس: 82]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، و",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«يد الله ملأى لا يغيضها نفقة، سحاء الليل والنهار»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[البخاري: 7411؛ مسلم: 993]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وكثرة الخلق واختلاف لغاتهم وتزاحم أصواتهم لا يوقع في علمه التباسا، ولا تشغله مسألة عن أخرى، كما لا تضيق قدرته بإطعامهم وإجابتهم. وعطاؤه الدنيوي يجري للمؤمن وغيره؛ فقد مكن لذي القرنين وآتاه من كل شيء سببا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَـٰهُ مِن كُلِّ شَىْءٍ سَبَبًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الكهف: 84]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وكان لفرعون ملك وأنهار يفتخر بها: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَـٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَـٰذِهِ ٱلْأَنْهَـٰرُ تَجْرِى مِن تَحْتِىٓ ۖ أَفَلَا تُبْصِرُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الزخرف: 51]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، فلا تجعل وفرة العطاء الدنيوي وحدها ميزان القرب. وعطية المخلوق تقيدها قلة ما عنده أو خوف نفاده أو ملله من الإلحاح، أما سؤال الغني الكريم فلا يصغر بحجة كثرة الطالبين أو عظم المطلوب. ولهذا قال ﷺ: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إذا دعا أحدكم فلا يقل اللهم اغفر لي إن شئت، ولكن ليعزم المسألة وليعظم الرغبة، فإن الله لا يتعاظمه شيء أعطاه»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مسلم: 2679]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "؛ فتتسع الرغبة في كل خير مشروع، مع بقاء الأدب وترك الاعتداء، فلا يسأل ما يناقض حكم الله، كالنبوة بعد خاتم النبيين. ويختم الحديث هذا الامتداد في الرجاء بمسؤولية لا تسقط: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "«إنما هي أعمالكم أحصيها لكم ثم أوفيكم إياها»",
            "color": "204D80",
            "bold": true
          },
          {
            "text": ". فالغنى والرحمة لا يعنيان إهمال الخلق؛ هو المحيط الحفيظ الحسيب الرقيب الشهيد، وقد أحصاهم وعدهم عدا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[مريم: 94]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، وجعل عليهم حفظة كراما كاتبين يعلمون ما يفعلون: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَإِنَّ عَلَيْكُمْ لَحَـٰفِظِينَ كِرَامًا كَـٰتِبِينَ يَعْلَمُونَ مَا تَفْعَلُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الانفطار: 10–12]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". وقد ينسى الإنسان فعله ولا يضيع عند الله: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[المجادلة: 6]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ويجد يومئذ ما عمل حاضرا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿وَوُضِعَ ٱلْكِتَـٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَـٰوَيْلَتَنَا مَالِ هَـٰذَا ٱلْكِتَـٰبِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا ۚ وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًا ۗ وَلَا يَظْلِمُ رَبُّكَ أَحَدًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الكهف: 49]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ومن يعمل مثقال ذرة خيرا يره ومن يعمل مثقال ذرة شرا يره: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[الزلزلة: 7–8]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ويتمنى صاحب السوء لو أن بينه وبين عمله أمدا بعيدا: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[آل عمران: 30]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": ". ومن الجزاء ما يظهر في الحياة الطيبة للمؤمن العامل للصالحات: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿مَنْ عَمِلَ صَـٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النحل: 97]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ومنه ما يعاقب به الإنسان على سوئه: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَـٰبِ ۗ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النساء: 123]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، ثم تأتي التوفية الكاملة في الآخرة. فمن وجد خيرا حمد الله الذي هداه إليه وأعانه عليه وقبله منه وأثابه، ومن وجد غيره رجع باللوم إلى تفريطه، كما قال تعالى: ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "﴿مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ ۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ﴾",
            "color": "176744",
            "bold": true
          },
          {
            "text": " ",
            "color": "000000",
            "bold": true
          },
          {
            "text": "[النساء: 79]",
            "color": "5B626B",
            "bold": true
          },
          {
            "text": "، مع الإيمان بأن الجميع داخل في علم الله وقدره. فلا يحتج العبد بالقدر على ذنبه، ولا يحمل تبعة تقصيره على غيره، ولا ينتظر حتى يكون اللوم ندما لا يصلح ما فات؛ بل يحاسب نفسه الآن، ويرد الحق ويتوب ويستعين بربه على إصلاح العمل. وهكذا يعود آخر الحديث إلى أوله: عدل لا يظلم صاحبه، ورحمة تدعوه إلى الرجوع، وافتقار يحرره من الغرور، وعمل محفوظ يحمله على صدق الاستعداد للقاء الله.",
            "color": "000000",
            "bold": true
          }
        ],
        "hyperlinks": []
      }
    ],
